import Foundation

// warnings.txt is generated by unmodified osfans/MCPDict tools/make.py -c -i
// in our data workflow. Only use diagnostics for the exact source revision.
actor UpstreamDiagnostics {
    static let shared = UpstreamDiagnostics()
    private var cached = [String: String]()
    func log(for table: TablePackage) async throws -> String {
        let text: String
        if let existing = cached[table.sourceCommit] { text = existing }
        else {
            struct Manifest: Decodable {
                let sourceCommit: String
                let diagnosticsURL: URL
            }
            let data = try await UpstreamTables.get(URL(string: "https://github.com/ghehyoein/MCPDict-iOS/releases/latest/download/diagnostics.json")!)
            let manifest = try JSONDecoder().decode(Manifest.self, from: data)
            guard manifest.sourceCommit == table.sourceCommit else { return "" }
            let url = manifest.diagnosticsURL
            guard url.host == "github.com", url.path.hasPrefix("/ghehyoein/MCPDict-iOS/releases/download/") else { return "" }
            let raw = try await UpstreamTables.get(url)
            text = String(data: raw, encoding: .utf16) ?? String(data: raw, encoding: .utf8) ?? ""
            cached[table.sourceCommit] = text
        }
        return Self.extract(text, name: table.name)
    }
    static func extract(_ text: String, name: String) -> String {
        var active = false, lines = [String]()
        for line in text.components(separatedBy: .newlines) {
            if !line.hasPrefix("\t"), !line.isEmpty { active = line.contains("（" + name + "）-") }
            else if active, line.hasPrefix("\t") { lines.append(String(line.dropFirst())) }
        }
        return lines.joined(separator: "\n")
    }
}

